// dom-writer.js - the ONLY module that touches the DOM. Takes render.js's
// pure view model and a `document`-shaped object (the real browser
// `document` in production; a minimal hand-rolled shim in
// board/web/test/dom-writer.test.js) and writes it into `root`.
//
// Deliberately uses only createElement/appendChild/textContent/className/
// setAttribute - the smallest DOM surface that can express this board -
// so the same code runs unmodified against Node's test shim (task 5.5's
// "render into a minimal DOM shim").
//
// Visual authority: the reviewed mockup brief
// (docs/design/2026-07-23-ui-mockup-brief.md) and design rev 5 S5.2's
// composition rules BIND (three registers only, verbatim words, honesty
// chrome, bagged/dark dignity); docs/design/mockups/2026-07-26-claude-
// design-board/'s five owner-generated variants STEER (owner ruling,
// 2026-07-26: NO SINGLE KEEPER - build the SHARED language, iterate later).
// #62 built that shared language: lane label plates with purpose
// subtitles, a footer status strip, a brand wordmark, the 2b track-
// schematic (trains/gates) + 1b Solari-board (dispatches) structural
// merge - still structural fidelity, not pixel-for-pixel, per the mock
// doctrine ("direction, never contract"). Further slices (specific
// elements from specific variants, per the owner ruling) remain open on
// issue #1.
//
// #28/#12: this module ALSO renders clickable provenance (a car/gate/
// dispatch subject or a train's declared ticket becomes an anchor when the
// wire supplies both a GitHub identity and the entry's own recordDir/
// ticket token) and the car-health-bar badge (#12) - both built from
// board/web/js/links.js and board/web/js/findings.js's pure helpers; this
// file's only job is turning their output into DOM.
//
// #69 (owner fast-follow: "closes back up every page refresh"): the
// conditions strip's open/collapsed state is PULLED from an already-loaded
// openState object (condition-open-state.js's pure shape) and REAPPLIED on
// every render - never captured by scraping the outgoing DOM before
// clearing it. app.js is the single source of truth: it reads sessionStorage
// fresh before each repaint (surviving both a DOM rebuild and a page
// refresh identically, since both start from the SAME persisted read) and
// keeps it current via a 'toggle' event listener, independent of render
// timing. This file only ever WRITES the `open` attribute a caller already
// decided; it never reads sessionStorage itself (dom-writer.js stays
// impure-storage-free, matching this module's own "the ONLY module that
// touches the DOM" boundary - sessionStorage is browser state, not DOM).
import { buildRecordLink, buildIssueLink, buildVocabLink, vocabFilenameForDiscoveryDetail } from './links.js';
import { formatClockDuration } from './format.js';
import { defaultOpenState, isGroupOpen } from './condition-open-state.js';

function el(doc, tag, className, text) {
  const node = doc.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function registerClass(register) {
  return `register-${register}`;
}

// #28: renders an <a> (quiet provenance affordance, board.css's
// .provenance-link) when href is truthy, or a plain element otherwise -
// "no link, never a broken one" (issue #28's own escape hatch). CORRECTED
// (#28/#12 fix cycle round 2 MINOR-2: "the className is IDENTICAL either
// way" was literally false): the BASE className is preserved either way (a
// caller's querySelectorAll('.car-subject') finds the element regardless
// of which tag it rendered as), but 'provenance-link' is APPENDED only on
// the linked form so board.css's quiet-affordance styling applies only
// there - the two className strings differ by exactly that one token.
function factOrLink(doc, className, text, href) {
  if (href) {
    const anchor = el(doc, 'a', `${className} provenance-link`, text);
    anchor.setAttribute('href', href);
    anchor.setAttribute('rel', 'noopener');
    return anchor;
  }
  return el(doc, 'span', className, text);
}

// #12: the health-trend badge text - a compact glyph + word + the family's
// own Major-count series, so the number itself (never just a color) carries
// the evidence (HAVAGLANCE: a glance must transmit the WHOLE story, and a
// bare color dot would not). 'first-round'/'unknown' get NO register class
// (neutral, muted text-dim via board.css) - Majors on round 1 alone is
// normal traffic in this shop, never alarming, and an unparseable findings
// shape is Law 1's honest-unknown, never a guessed calm OR guessed hot.
function healthTrendBadgeText(healthTrend) {
  const series = healthTrend.majorsSeries ? healthTrend.majorsSeries.join('→') : null;
  switch (healthTrend.trend) {
    case 'converged':
      return `▼ converged (${series})`;
    case 'declining':
      return `▼ declining (${series})`;
    case 'stalled':
      return `● stalled (${series})`;
    case 'first-round':
      return 'round 1 (no trend yet)';
    default:
      return 'trend: unknown';
  }
}

// #71 (clickable provenance, remaining #28 surfaces): a superseded entry is
// a PRIOR record for the SAME subject that lost to the row's own winner
// (board/fold/algorithm.go's foldDispatchSubject - precedence, then
// latest-at) - it lives in the SAME store-root-relative directory as the
// row's own recordDir (board/assemble's one-directory-per-subject
// convention, the same one #28's recordDir already relies on), so no new
// wire field is needed: every superseded entry links through the row's
// OWN recordDir, never re-derived. Honest-absence (null, not an empty
// list) when there is nothing to supersede - matches every other
// honest-absence convention in this file (declared-not-observed,
// renderHistorySummary).
//
// #71 fix-cycle round 2 (MAJOR-R1-1, owner ruling recorded at issue #69,
// 2026-07-27): round 1 appended this block as a SIBLING of the row/chip
// into the shared grid/flex container (.solari-rows / .track-cars), so a
// wrap boundary could land the block next to a DIFFERENT subject's cell -
// measured live: a 5-line unlabelled timestamp stack wrapped onto the line
// below the subject that owned it, immediately beside an unrelated
// subject's own cell. The owner ruling: nest the block INSIDE its owner
// row/chip (a DOM child, so it can never be laid out by the grid/flex
// container as an independent cell/item and can never orphan) behind a
// quiet per-row <details>/<summary> disclosure, COLLAPSED by default - the
// SAME chrome idiom `renderBoardConditionsStrip` (#30) already uses for
// exactly this "quiet, expandable, never a headline" posture. This
// preserves #67's density: a collapsed disclosure is a single summary
// line, not the raw list.
//
// #69/#71-M1 (disclosed, not owner-ruled - see fix-cycle round 2 report):
// this disclosure's open/closed state is EPHEMERAL, not persisted through
// condition-open-state.js's sessionStorage mechanism. Chosen as the
// MINIMAL option: #69's persistence keys by a closed, small vocabulary
// (the strip + a handful of condition CODES, board/store/condition_
// severity.go) but a per-row disclosure would need one key per SUBJECT -
// an open-ended, store-size-dependent key set with no eviction story, on a
// mechanism (sessionStorage) that already has no size ledger. Ephemeral
// also matches this file's own render cycle unforced: `renderBoard`
// (this file's own top-level export, cited by SYMBOL - fix cycle round 3
// MAJOR-R2-2, this comment's own bare "(line 141)" was already false the
// instant round 2 committed it, MAJOR-R1-4's class reproduced in the same
// commit as the lecture about it, docs/contracts/gating-matrix.md:49)
// clears `root.textContent` on every repaint, so even a native `open`
// attribute set by a prior render is already discarded before the next
// paint - persisting it would require NEW capture-and-reapply plumbing
// mirroring #69's, not a re-use of it. Reopens on the next click, same as
// every `<details>` on the web with no persistence wired at all.
//
// #69/#71 fix-cycle round 2 (MINOR-R1-2), CORRECTED fix cycle round 3
// (MAJOR-R2-3): the wire schema now constrains superseded[] items to
// {kind: string, at: string} both required (schema/yard-snapshot.schema.
// json's $defs.dispatchSupersededItem), but that constraint is NEVER
// enforced on the runtime hop a browser actually takes - $defs.lane.data
// (schema/yard-snapshot.schema.json's own $comment explains why: a lane's
// data shape is chosen by which lane it is, not one closed schema union)
// does not $ref dispatchesPayload/trainsPayload, so ingest.js's validator
// (validate.js, the real vendored cfworker-json-schema engine) applies NO
// constraint to superseded[] items - measured: a malformed item validates
// clean through it, before and after this schema addition. The ONLY
// consumer of the new $def is scripts/tests/WirePayload.Tests.ps1's
// fragment extraction, which wraps the $def standalone and therefore sees
// a constraint the real runtime validator never applies. THIS FUNCTION'S
// OWN FILTER, below, is the entire runtime protection, full stop - not
// "defense in depth" alongside a wire-level gate that does not exist. A
// malformed item (missing/non-string kind or at) is skipped, never
// rendered as literal "undefined undefined" (Law 1: honest-absence over a
// guessed/garbled fact) - matching this file's other honest-absence
// conventions (declared-not-observed, renderHistorySummary). If EVERY item
// in the array is malformed, the whole disclosure renders as absent (no
// empty <details> with a "0 superseded" summary and nothing inside it) -
// the same "never an empty list" posture the original honest-absence
// comment above already commits to.
function renderSupersededDisclosure(doc, wrapperClassName, entryClassName, superseded, recordDir, linkCfg) {
  if (!superseded || superseded.length === 0) return null;
  const validItems = superseded.filter((item) => typeof item?.kind === 'string' && typeof item?.at === 'string');
  if (validItems.length === 0) return null;
  const details = el(doc, 'details', `${wrapperClassName}-disclosure`);
  details.appendChild(el(doc, 'summary', `${wrapperClassName}-summary`, `${validItems.length} superseded`));
  const wrap = el(doc, 'div', wrapperClassName);
  for (const item of validItems) {
    // VERBATIM kind + at - never translated, same posture as every other
    // detector-owned string this file renders.
    wrap.appendChild(factOrLink(doc, entryClassName, `${item.kind} ${item.at}`, buildRecordLink(linkCfg, recordDir)));
  }
  details.appendChild(wrap);
  return details;
}

function healthTrendRegisterClass(trend) {
  if (trend === 'converged' || trend === 'declining') return 'register-nominal';
  if (trend === 'stalled') return 'register-needs-attention';
  return ''; // first-round / unknown: neutral, no register class (board.css's own muted default)
}

/**
 * @param {Document} doc
 * @param {Element} root
 * @param {ReturnType<import('./render.js').buildBoardViewModel>} vm
 * @param {{connected: boolean}} connection
 * @param {{strip: boolean, groups: Record<string, boolean>}} [openState] -
 *   #69: the conditions strip's persisted open/collapsed state, already
 *   loaded by the caller (app.js) - defaults to fully-collapsed so every
 *   existing call site (tests, any caller that predates this ticket) keeps
 *   its prior behaviour unchanged.
 */
export function renderBoard(doc, root, vm, connection, openState = defaultOpenState()) {
  root.textContent = ''; // clear() without needing a real DOM API for it

  root.appendChild(renderChrome(doc, vm, connection));

  // #28: the three link-building primitives, read off the view model ONCE
  // per render and threaded down to every lane body that needs them -
  // never re-read from vm inside a deeply nested renderer.
  const linkCfg = {
    githubRepoUrl: vm.githubRepoUrl,
    githubRef: vm.githubRef,
    githubArtifactsPrefix: vm.githubArtifactsPrefix
  };

  const lanesRoot = el(doc, 'section', 'lanes');
  const total = vm.lanes.length;
  vm.lanes.forEach((lane, index) => {
    lanesRoot.appendChild(renderLane(doc, lane, index + 1, total, linkCfg));
  });
  root.appendChild(lanesRoot);

  root.appendChild(renderFooter(doc, vm, linkCfg, openState));
}

// #62: shared visual language (owner ruling: no single keeper) - every one
// of the five mockup variants opens with a condensed wordmark ("STARCAR")
// ahead of the honesty chrome. Static presentational text, not data - the
// single strongest common signal across all five variants (README.md's
// "What the direction already gets right").
function renderChrome(doc, vm, connection) {
  const chrome = el(doc, 'header', 'chrome');

  const brand = el(doc, 'div', 'brand');
  brand.appendChild(el(doc, 'span', 'brand-name', 'STARCAR'));
  brand.appendChild(el(doc, 'span', 'brand-subtitle', 'YARD BOARD'));
  chrome.appendChild(brand);

  if (vm.demoMode) {
    chrome.appendChild(el(doc, 'div', 'demo-banner', 'DEMO DATA'));
  }

  chrome.appendChild(el(doc, 'div', 'as-of', `as of ${vm.asOf ?? '(no successful scan yet)'}`));

  const connectionClass = connection.connected ? 'connection-connected' : 'connection-disconnected';
  chrome.appendChild(
    el(doc, 'div', connectionClass, connection.connected ? 'connected' : 'disconnected - showing last known')
  );

  return chrome;
}

// #62: the footer status strip (shared across every mockup variant) - moved
// here from the top chrome: registry lane completeness, the real
// storePathDisplay wire field (never rendered anywhere before this pass -
// already publication-safe per schema/yard-snapshot.schema.json's
// config.storePathDisplay property - cited by SYMBOL, not line, #28/#12 fix
// cycle round 2 MAJOR-1: this comment's own "  :191" line citation was
// falsified by a LATER commit in this same train that grew the schema file,
// exactly the trap poll.go's own "cited by symbol, not line" convention
// exists to avoid), and the #30 board-conditions strip. Store-record/fold
// counts ("store: 65 -> 17 dispatches") appear in the mockups too but
// carry NO wire field (schema/yard-snapshot.schema.json has no such field)
// - inventing one client-side would be a second copy of server-owned
// arithmetic (Law 6) and adding one server-side is a wire change, out of
// this ticket's scope.
// CORRECTED (#62 fix cycle round 2, review round 1 MINOR-1 - this comment
// used to say "routed to issue #1" while nothing had actually been posted
// there, a carrier-rule miss): now actually routed - see issue #1, comment
// https://github.com/polecatspeaks/StarCar/issues/1#issuecomment-5085235534
// (2026-07-26), item 2.
function renderFooter(doc, vm, linkCfg, openState) {
  const footer = el(doc, 'footer', 'board-footer');

  const laneCountText = `registry declares ${vm.laneCompleteness.declared} lane(s) - ${vm.laneCompleteness.observed} rendered`;
  footer.appendChild(el(doc, 'div', 'lane-count', laneCountText));

  if (vm.storePathDisplay) {
    footer.appendChild(el(doc, 'div', 'store-path', `store: ${vm.storePathDisplay}`));
  }

  if (vm.boardConditionGroups.length > 0) {
    footer.appendChild(renderBoardConditionsStrip(doc, vm, linkCfg, openState));
  }

  return footer;
}

// #30: CHROME, not headline (item 3) - a native <details>/<summary> pair
// needs zero JS to expand/collapse, so this is the smallest DOM surface
// that satisfies "a single summary line that expands" without adding a
// click handler. COLLAPSED BY DEFAULT (openState.strip false, the same
// default this repo has always shipped) regardless of severity - even an
// all-FLAG board never auto-expands the strip UNLESS a reader has
// previously opened it this session (#69) - the yard lanes staying above
// the fold on FIRST paint is still the whole point of chrome placement.
//
// data-conditions-strip identifies this element for app.js's toggle
// listener (#69) - a stable marker independent of className, which board.css
// may restyle without breaking the persistence wiring.
function renderBoardConditionsStrip(doc, vm, linkCfg, openState) {
  const strip = el(doc, 'details', `board-conditions-strip ${registerClass(vm.boardConditionsRegister)}`);
  strip.setAttribute('data-conditions-strip', '');
  if (openState && openState.strip) strip.setAttribute('open', '');
  strip.appendChild(el(doc, 'summary', `board-conditions-summary ${registerClass(vm.boardConditionsRegister)}`, vm.boardConditionSummary));

  const groups = el(doc, 'ul', 'board-condition-groups');
  for (const group of vm.boardConditionGroups) {
    groups.appendChild(renderBoardConditionGroup(doc, group, linkCfg, openState));
  }
  strip.appendChild(groups);
  return strip;
}

// #69/#71 (clickable provenance, extending #28 to the board-conditions
// surface): the ONE place a condition instance's honest link target is
// chosen. A "discovery" (NOTE-tier, undeclared kind/outcome VALUE - never a
// store subject) links to the schema/vocab/*.json file that would declare
// it; every other condition class links to its own recordDir when the wire
// supplied one (a config-load fault, an aggregate count, or a client-raised
// condition never has one, and factOrLink's own href-is-falsy branch
// degrades those to identical-layout plain text - "no link, never a broken
// one", #28's own rule, unchanged).
function boardConditionInstanceHref(linkCfg, group, instance) {
  if (group.code === 'discovery') {
    return buildVocabLink(linkCfg, vocabFilenameForDiscoveryDetail(instance.detail));
  }
  return buildRecordLink(linkCfg, instance.recordDir);
}

// #30 (GROUP BY CLASS): one row per condition CODE, itself a <details> -
// "expandable to per-instance details" - collapsed by default (#69: unless
// this code was previously opened THIS SESSION - isGroupOpen defaults to
// closed for any code with no recorded entry, which is exactly how a
// newly-appearing condition class still renders per #30's original rule).
// data-condition-code identifies this element for app.js's toggle listener.
function renderBoardConditionGroup(doc, group, linkCfg, openState) {
  const item = el(doc, 'li', `board-condition-group ${registerClass(group.register)}`);
  const details = el(doc, 'details', 'board-condition-group-details');
  details.setAttribute('data-condition-code', group.code);
  if (isGroupOpen(openState, group.code)) details.setAttribute('open', '');
  details.appendChild(el(doc, 'summary', 'board-condition-group-summary', `${group.code} (x${group.count})`));
  const instances = el(doc, 'ul', 'board-condition-instances');
  for (const instance of group.instances) {
    // VERBATIM - never translated, the same posture as every other
    // detector-owned string this repo renders (state words, outcome words).
    // #69/#71: rendered through factOrLink so a resolvable target becomes a
    // real link (quiet .provenance-link affordance) with IDENTICAL layout
    // to the plain form when no target resolves.
    instances.appendChild(
      factOrLink(
        doc,
        `board-condition-instance ${registerClass(instance.register)}`,
        instance.detail,
        boardConditionInstanceHref(linkCfg, group, instance)
      )
    );
  }
  details.appendChild(instances);
  item.appendChild(details);
  return item;
}

// #62: lane label PLATE (ordinal + title + purpose subtitle + freshness
// lines) beside its content - the shared layout across every mockup
// variant (1a's grid-template-columns label column, 2b's numbered plate,
// 1c's surfaced card). `index`/`total` are the lane's position in the
// already-known, already-ordered snapshot.lanes array (EXPECTED_LANE_IDS'
// own registry order, restated at the view - render.test.js pins this
// order) - a structural ordinal about DECLARED lane position, never new
// data and never a second copy of anything server-owned.
function renderLane(doc, lane, index, total, linkCfg) {
  const section = el(doc, 'article', `lane lane-${lane.id} ${registerClass(lane.register)}`);

  const plate = el(doc, 'div', 'lane-plate');
  const heading = el(doc, 'div', 'lane-heading');
  const ordinal = el(doc, 'span', 'lane-ordinal', String(index));
  ordinal.setAttribute('title', `lane ${index} of ${total} declared`);
  heading.appendChild(ordinal);
  heading.appendChild(el(doc, 'h2', 'lane-title', lane.title));
  plate.appendChild(heading);
  if (lane.purpose) {
    plate.appendChild(el(doc, 'div', 'lane-purpose', lane.purpose));
  }
  plate.appendChild(el(doc, 'div', 'lane-primary', lane.primary));
  if (lane.secondary) {
    plate.appendChild(el(doc, 'div', 'lane-secondary', lane.secondary));
  }
  section.appendChild(plate);

  const content = el(doc, 'div', 'lane-content');
  content.appendChild(renderLaneBody(doc, lane.body, linkCfg));
  section.appendChild(content);

  return section;
}

function renderLaneBody(doc, body, linkCfg) {
  switch (body.kind) {
    case 'trains':
      return renderTrains(doc, body, linkCfg);
    case 'gates':
      return renderGates(doc, body, linkCfg);
    case 'dispatches':
      return renderDispatches(doc, body, linkCfg);
    case 'freight':
      return renderFreight(doc, body, linkCfg);
    case 'dark':
      return el(doc, 'div', 'lane-body lane-body-dark', body.text);
    case 'bagged':
      return el(doc, 'div', 'lane-body lane-body-bagged', body.text);
    case 'no-renderer':
      return el(doc, 'div', 'lane-body lane-body-no-renderer', 'no renderer for this payload');
    default:
      return el(doc, 'div', 'lane-body lane-body-unknown', `unrecognised lane body kind: '${body.kind}'`);
  }
}

// #67 (HONESTY CONSTRAINT, Law 4 + absence-blindness): the one summary line
// shared by both filtered lanes - QUIET CHROME (#62 visual idiom: nominal
// register, small text, never a headline), rendered only when render.js's
// historySummary is non-null (hiddenCount > 0) so an unfiltered lane never
// carries a "showing 0 of 0" noise line.
function renderHistorySummary(doc, historySummary) {
  if (!historySummary) return null;
  return el(doc, 'div', `history-summary ${registerClass('nominal')}`, historySummary);
}

// TRAINS: track-schematic direction (mockup merge 2b) - each train is a
// labeled track holding its cars in sequence.
function renderTrains(doc, body, linkCfg) {
  const wrap = el(doc, 'div', 'lane-body lane-body-trains');
  const summary = renderHistorySummary(doc, body.historySummary);
  if (summary) wrap.appendChild(summary);
  for (const train of body.trains) {
    const track = el(doc, 'div', 'track');
    track.appendChild(el(doc, 'div', 'track-title', `${train.title} (${train.id})`));
    // #28: the manifest's own declared ticket refs, rendered as issue
    // links - a train with none renders no ticket strip at all (never an
    // empty one), matching every other honest-absence convention here.
    if (train.tickets.length > 0) {
      const ticketsEl = el(doc, 'div', 'train-tickets');
      for (const ticket of train.tickets) {
        ticketsEl.appendChild(factOrLink(doc, 'ticket-link', ticket, buildIssueLink(linkCfg, ticket)));
      }
      track.appendChild(ticketsEl);
    }
    const cars = el(doc, 'div', 'track-cars');
    for (const car of train.cars) {
      const chip = el(doc, 'div', `car-chip ${registerClass(car.stateRegister)}`);
      // #75: the VISIBLE identity is the human task-id when the wire
      // supplies one (returned records only, as of this landing - #76 is
      // the dispatched-record half), falling back honestly to the
      // record-dir hash subject when absent (Law 1: never invent a
      // label). The full subject hash stays reachable EITHER WAY through
      // the native title tooltip (the #62 pattern, extended here to the
      // chip for the first time) - the provenance link keeps resolving by
      // recordDir exactly as before, unaffected by which text is visible.
      const carSubject = factOrLink(doc, 'car-subject', car.taskId ?? car.subject, buildRecordLink(linkCfg, car.recordDir));
      carSubject.setAttribute('title', car.subject);
      chip.appendChild(carSubject);
      chip.appendChild(el(doc, 'span', 'car-role', car.role.label));
      // VERBATIM state word - never translated (mockup brief).
      chip.appendChild(el(doc, 'span', 'car-state', car.state));
      if (car.outcome) {
        chip.appendChild(el(doc, 'span', `car-outcome ${registerClass(car.outcomeRegister)}`, car.outcome));
      }
      if (car.gate) {
        chip.appendChild(el(doc, 'span', 'car-gate', car.gate));
      }
      // #71 fix-cycle r2 (MAJOR-R1-1): appended INSIDE the chip, never to
      // `cars` (the flex-wrap container) - the disclosure can only ever
      // grow ITS OWN chip's box, never bleed onto a neighbouring chip.
      const supersededDisclosure = renderSupersededDisclosure(doc, 'car-superseded', 'car-superseded-entry', car.superseded, car.recordDir, linkCfg);
      if (supersededDisclosure) chip.appendChild(supersededDisclosure);
      cars.appendChild(chip);
    }
    track.appendChild(cars);
    if (train.declaredNotObserved.length > 0) {
      track.appendChild(
        el(doc, 'div', 'declared-not-observed', `declared, not yet observed: ${train.declaredNotObserved.join(', ')}`)
      );
    }
    wrap.appendChild(track);
  }
  return wrap;
}

// GATES: signal-head direction (mockup merge 2b) - a small verdict light
// per gate, verdict word VERBATIM.
//
// #62 N3 (fix cycle round 2, review round 1 NOTE-3): an empty-but-live
// gates lane used to render a blank content pane - honest (body.gates is
// really []) but reads as a rendering hole rather than a stated absence,
// unlike freight's "no equipment on this lane" and fuel's "data held, not
// surfaced". Derived honestly from the same data already in hand (zero
// entries in THIS fold's gates array) - never invented, never a guess
// about why it is empty.
function renderGates(doc, body, linkCfg) {
  const wrap = el(doc, 'div', 'lane-body lane-body-gates');
  if (body.gates.length === 0) {
    wrap.appendChild(el(doc, 'div', 'lane-body-gates-empty', 'no gates in this fold'));
    return wrap;
  }
  for (const gate of body.gates) {
    const signal = el(doc, 'div', `signal ${registerClass(gate.outcomeRegister)}`);
    signal.appendChild(factOrLink(doc, 'signal-name', gate.name, buildRecordLink(linkCfg, gate.recordDir)));
    signal.appendChild(el(doc, 'span', 'signal-outcome', gate.outcome)); // VERBATIM
    signal.appendChild(el(doc, 'span', 'signal-at', gate.at));
    // #12: the car health bar - present ONLY on a review-round family's
    // LATEST round (render.js's computeHealthTrends already scoped this;
    // this renderer just draws whatever it was handed).
    if (gate.healthTrend) {
      signal.appendChild(
        el(
          doc,
          'span',
          `health-trend ${healthTrendRegisterClass(gate.healthTrend.trend)}`.trim(),
          healthTrendBadgeText(gate.healthTrend)
        )
      );
    }
    wrap.appendChild(signal);
  }
  return wrap;
}

// DISPATCHES: Solari split-flap direction (mockup merge 1b) - dense
// monospace rows: identity (task-id when the wire has one, else the
// record-dir hash subject - #75 fix cycle r2, R1-m3: this comment used to
// say plain "subject", stale as of this function's own identity-cluster
// build below), state word, elapsed.
function renderDispatches(doc, body, linkCfg) {
  const wrap = el(doc, 'div', 'lane-body lane-body-dispatches');
  wrap.appendChild(
    el(doc, 'div', 'yard-inventory-count', `${body.yardInventoryCount} in yard inventory (unassigned)`)
  );
  const summary = renderHistorySummary(doc, body.historySummary);
  if (summary) wrap.appendChild(summary);
  const rows = el(doc, 'div', 'solari-rows');
  for (const d of body.dispatches) {
    const row = el(doc, 'div', `solari-row ${registerClass(d.stateRegister)}${d.assigned ? '' : ' unassigned'}`);
    // #71 fix cycle r3 (MAJOR-R2-1): the subject/state/elapsed cluster lives
    // in its OWN wrapper (`solari-row-main`), never as direct flex children
    // of `.solari-row` itself - see board.css's `.solari-row`/`.solari-row-
    // main` comment for why (round 2's `flex-wrap: wrap` on `.solari-row`
    // wrapped this cluster onto a second line too, not just the disclosure).
    const main = el(doc, 'div', 'solari-row-main');
    // #75: the row's VISIBLE identity is the human task-id when the wire
    // supplies one (RETURNED records only, as of this landing - #76 is the
    // dispatched-record half), falling back honestly to the record-dir
    // hash subject id when absent (Law 1: never invent a label). Neither
    // the provenance link (still keyed off d.recordDir) nor the title
    // tooltip below is affected by which text is visible.
    const subject = factOrLink(doc, 'solari-subject', d.taskId ?? d.subject, buildRecordLink(linkCfg, d.recordDir));
    // #62: board.css truncates a long subject id (or task-id) with an
    // ellipsis (the fixed-height dispatches grid) - the native title
    // tooltip keeps the full SUBJECT HASH reachable, verbatim, regardless
    // of which text is visible (#75: never silently lost behind a
    // friendlier label either). Survives becoming a link (#28) - the title
    // attribute goes on the anchor/span either way.
    subject.setAttribute('title', d.subject);
    main.appendChild(subject);
    main.appendChild(el(doc, 'span', 'solari-state', d.state)); // VERBATIM
    if (d.elapsedSeconds !== null) {
      // #67 (FORMAT NIT): compact clock time, never "272s" - the ONE
      // formatter every duration on this board shares (format.js, Law 6).
      main.appendChild(el(doc, 'span', 'solari-elapsed', formatClockDuration(d.elapsedSeconds)));
    }
    row.appendChild(main);
    // #71 fix-cycle r2 (MAJOR-R1-1), fix cycle r3 (MAJOR-R2-1): appended
    // INSIDE the row, never to `rows` (the grid container) - the disclosure
    // can only ever grow ITS OWN row's grid cell, never wrap onto a
    // neighbouring subject's cell. Appended AFTER `main`, never inside it,
    // so `.solari-row`'s column-direction layout stacks it below the
    // single-line cluster rather than letting it compete for space on that
    // cluster's own flex line.
    const supersededDisclosure = renderSupersededDisclosure(doc, 'solari-superseded', 'solari-superseded-entry', d.superseded, d.recordDir, linkCfg);
    if (supersededDisclosure) row.appendChild(supersededDisclosure);
    rows.appendChild(row);
  }
  wrap.appendChild(rows);
  return wrap;
}

// FREIGHT: the inbound ticket queue (#84) - one row per queued issue. TWO
// links per row, deliberately different targets (#84 fix cycle round 2,
// R1-m3 - recordDir was already carried on the wire but never rendered;
// this fixes that rather than dropping the field, since the wire schema
// already advertises it as "#28 clickable provenance"): the TITLE links
// DIRECTLY to the issue's github.com URL (t.url, verbatim from the wire,
// never re-derived - Law 6, there is no repo-relative path to assemble for
// a value the record already states outright); the NUMBER links to the
// ticket's own STORE record directory via linkCfg/buildRecordLink, the same
// convention every other lane's subject/name token already uses (#28).
// Content provenance and store provenance are two different facts about
// the same row - the trains lane already carries this exact split (a car's
// subject links to its recordDir, its manifest ticket refs link to
// github.com issues); freight is the same split on one row instead of two
// tokens across two lanes.
//
// Same "empty-but-live reads as a stated absence, not a rendering hole"
// posture as renderGates' N3 precedent above: a genuinely empty queue says
// so, in its own honest line - paired with the lane's OWN freshness
// secondary line (composeLines, render.js), which is what actually carries
// the never-run/ran-empty/stale distinction (#84's Law 1 requirement) -
// this function never re-states or duplicates that distinction itself.
function renderFreight(doc, body, linkCfg) {
  const wrap = el(doc, 'div', 'lane-body lane-body-freight');
  if (body.tickets.length === 0) {
    wrap.appendChild(el(doc, 'div', 'lane-body-freight-empty', 'no tickets in the queue'));
    return wrap;
  }
  const rows = el(doc, 'div', 'freight-rows');
  for (const t of body.tickets) {
    const row = el(doc, 'div', 'freight-row');
    row.appendChild(factOrLink(doc, 'freight-number', `#${t.number}`, buildRecordLink(linkCfg, t.recordDir)));
    row.appendChild(factOrLink(doc, 'freight-title', t.title, t.url));
    row.appendChild(el(doc, 'span', 'freight-status', t.status)); // VERBATIM
    rows.appendChild(row);
  }
  wrap.appendChild(rows);
  return wrap;
}

// render.js - the pure view-model builder (task 5.3). Turns a validated
// wire snapshot into plain-object view state; app.js's DOM writer (the only
// impure consumer) walks this shape. No DOM here on purpose: this keeps
// the composition-and-vocabulary logic testable in Node against real
// captured payloads (board/web/test/fixtures/real-snapshot.json).
import { composeRegister, composeLines, mostSevereRegister } from './compose.js';
import { hasRendererFor } from './lanes.js';
import { describeVocab } from './vocab.js';
import { computeHealthTrends } from './findings.js';
import { capTerminalHistory } from './history-filter.js';

// #62: lane-purpose subtitles (owner ruling: shared visual language, no
// single keeper - "lane plates with lane-purpose subtitles"). PRESENTATION
// ONLY, keyed by the same closed five-id registry lanes.js already pins
// (EXPECTED_LANE_IDS) - same posture as buildLaneBody's existing freight/
// fuel honesty text below, which is also client-side fixed prose keyed by
// lane id, not wire data (Car 4's precedent). Copy is lifted near-verbatim
// from docs/design/2026-07-23-ui-mockup-brief.md's own "Layout: five
// horizontal lanes" section so it is traceable to that source rather than
// invented. An id outside this set (the 6th-lane discovery path) gets no
// purpose line at all - never a guessed one.
//
// LANE ORDER NOTE (#62 fix cycle round 2, review round 1 MINOR-1): the
// keys above are listed in the ui-mockup-brief's illustrative order
// (trains, gates, dispatches, freight, fuel), but the actual rendered
// order follows lanes.js's EXPECTED_LANE_IDS (dispatches, gates, trains,
// freight, fuel) - the real, server-authoritative wire order
// (board/server/laneregistry.go), left untouched by this ticket (contract
// wins over illustrative direction, per the mock doctrine's own routing
// rule). This direction-vs-contract conflict is routed to issue #1, see
// https://github.com/polecatspeaks/StarCar/issues/1#issuecomment-5085235534
// (2026-07-26), item 1.
const LANE_PURPOSE = Object.freeze({
  trains: 'active work units - cars held in sequence',
  gates: 'review signals - verdict word rendered verbatim',
  dispatches: 'the raw worker feed',
  freight: 'the inbound ticket queue',
  fuel: 'the spend / usage gauge'
});

function lanePurpose(id) {
  return Object.prototype.hasOwnProperty.call(LANE_PURPOSE, id) ? LANE_PURPOSE[id] : null;
}

/**
 * Completeness guard (design rev 5 S5.2), restated at the view: the
 * mockup's "a lane count ... so a silently missing lane is detectable" is
 * only true if the view actually COMPARES the declared count
 * (config.laneCount) against what it observed, rather than only echoing
 * one of the two numbers.
 */
export function checkLaneCompleteness(snapshot) {
  const declared = snapshot.config.laneCount;
  const observed = snapshot.lanes.length;
  return { declared, observed, mismatch: declared !== observed };
}

/**
 * #30 (GROUP BY CLASS): one row per condition CODE, with a count and every
 * per-instance detail preserved (never discarded - "expandable to
 * per-instance details" per the owner-ruled design). Register stays
 * authoritative from the server per instance (Rule 4); the roll-up to one
 * register PER GROUP uses mostSevereRegister only as a defensive combinator
 * for the (never-expected-in-production) case of one code carrying mixed
 * registers - board/store/condition_severity.go is the ONE owned mapping
 * from code to tier, so in practice every instance of a given code already
 * shares one register.
 *
 * @param {Array<{code:string, detail:string, register:string, recordDir?:string}>} boardConditions
 */
export function groupBoardConditions(boardConditions) {
  const order = [];
  const byCode = new Map();
  for (const bc of boardConditions) {
    if (!byCode.has(bc.code)) {
      byCode.set(bc.code, { code: bc.code, register: bc.register, instances: [] });
      order.push(bc.code);
    }
    const group = byCode.get(bc.code);
    group.register = mostSevereRegister(group.register, bc.register);
    // #69/#71: recordDir carried through, never re-derived (Law 6) - the
    // wire's own store.BoardCondition.RecordDir when present, null when the
    // condition names no single subject/record (a config fault, an
    // aggregate count) or is a client-raised condition that never had one.
    group.instances.push({ detail: bc.detail, register: bc.register, recordDir: bc.recordDir ?? null });
  }
  return order.map((code) => {
    const group = byCode.get(code);
    return { code: group.code, register: group.register, count: group.instances.length, instances: group.instances };
  });
}

// #30 (HAVAGLANCE): the most-severe register across every group, so the
// COLLAPSED strip's own summary line can carry a color signal - "total
// transmission in a single look" (HAVAGLANCE) fails if a FLAG-tier
// condition is invisible until the reader expands the chrome. Defaults to
// 'nominal' (calm) when there are no groups at all - honest-empty, the same
// posture the rest of this repo gives a zero-of-zero state.
export function overallBoardConditionsRegister(groups) {
  return groups.reduce((worst, group) => mostSevereRegister(worst, group.register), 'nominal');
}

// #30 (SEVERITY PER CLASS -> PLACEMENT): the two-tier vocabulary this
// summary line speaks - NOTE-tier groups (register 'nominal' or
// 'in-progress', though in practice only 'nominal' is emitted server-side)
// count as "note(s)"; FLAG-tier groups (register 'needs-attention') count
// as "FLAG(S)". Counting INSTANCES (not distinct classes) - "1 FLAG + 2
// notes" reads as "how many things need attention", the HAVAGLANCE
// question a glance at chrome is meant to answer, not "how many kinds of
// thing".
export function summariseBoardConditionGroups(groups) {
  let flagCount = 0;
  let noteCount = 0;
  for (const group of groups) {
    if (group.register === 'needs-attention') {
      flagCount += group.count;
    } else {
      noteCount += group.count;
    }
  }
  const parts = [];
  if (flagCount > 0) parts.push(`${flagCount} FLAG${flagCount === 1 ? '' : 'S'}`);
  if (noteCount > 0) parts.push(`${noteCount} note${noteCount === 1 ? '' : 's'}`);
  return parts.length > 0 ? parts.join(' + ') : 'no conditions';
}

/**
 * @param {object} snapshot - a snapshot already validated against
 *   schema/yard-snapshot.schema.json (task 5.2's ingest.js gate).
 * @param {Array<{code:string, detail:string, register:string}>} clientConditions
 *   - board conditions raised BY THE VIEW itself (e.g. a discarded
 *   payload, a disconnect) - merged alongside the server's own `board`
 *   array, never replacing it.
 */
export function buildBoardViewModel(snapshot, clientConditions = []) {
  const vocab = snapshot.vocabularies;
  const completeness = checkLaneCompleteness(snapshot);

  // Rule 4 (design S5.2): a board condition's register is authoritative
  // from the server - the view NEVER recomputes it, only renders it.
  const boardConditions = [...snapshot.board, ...clientConditions];
  if (completeness.mismatch) {
    boardConditions.push({
      code: 'view-lane-count-mismatch',
      detail: `chrome declares ${completeness.declared} lane(s) but the snapshot carried ${completeness.observed}`,
      register: 'needs-attention'
    });
  }
  const boardConditionGroups = groupBoardConditions(boardConditions);
  const boardConditionSummary = summariseBoardConditionGroups(boardConditionGroups);
  const boardConditionsRegister = overallBoardConditionsRegister(boardConditionGroups);

  const lanes = snapshot.lanes.map((lane) => {
    const hasRenderer = hasRendererFor(lane);
    const register = composeRegister({ position: lane.position, positionDefs: vocab.positions, freshness: lane.freshness, hasRenderer });
    const lines = composeLines({ position: lane.position, positionDefs: vocab.positions, freshness: lane.freshness, hasRenderer });
    return {
      id: lane.id,
      title: lane.title,
      purpose: lanePurpose(lane.id),
      register,
      primary: lines.primary,
      secondary: lines.secondary,
      body: buildLaneBody(lane, vocab, hasRenderer)
    };
  });

  return {
    asOf: snapshot.asOf,
    demoMode: Boolean(snapshot.config.demoMode),
    // #62: real wire field (schema/yard-snapshot.schema.json's
    // config.storePathDisplay), already normalised server-side to be
    // publication-safe (never a raw absolute path - board/server/storepath.go)
    // and already validated by the schema on ingest - rendered for the first
    // time in the footer's honesty chrome below. No new data, no wire change.
    storePathDisplay: snapshot.config.storePathDisplay,
    // #28: the three primitives the view needs to build every provenance
    // link itself (board/web/js/links.js) - "" (never undefined) when
    // unconfigured, matching storePathDisplay's own always-a-string
    // contract above (a non-GitHub yard degrades to no links, never a
    // broken one).
    githubRepoUrl: snapshot.config.githubRepoUrl || '',
    githubRef: snapshot.config.githubRef || '',
    githubArtifactsPrefix: snapshot.config.githubArtifactsPrefix || '',
    laneCompleteness: completeness,
    boardConditions,
    boardConditionGroups,
    boardConditionSummary,
    boardConditionsRegister,
    lanes
  };
}

// #67 (owner fast-follow after #62 live-board feedback): a train has no
// top-level liveness state of its own (schema/yard-snapshot.schema.json's
// $defs.trainsPayload - only each CAR carries `state`); terminality is
// derived, never wire-native. A train is TERMINAL (fully returned, history-
// eligible) iff every declared manifest member has a record
// (declaredNotObserved is empty - an undelivered member is the owner's
// "queued", never terminal) AND every one of its cars already carries BOTH
// the one liveness state AND the one outcome whose register is nominal
// (car.stateRegister / car.outcomeRegister, already computed above by
// describeVocab against the wire's OWN liveness/outcomes defs - this reads
// those registers, it never recomputes or hardcodes a state/outcome word).
//
// #67 FIX CYCLE ROUND 2 (view-67-car-r2 MAJOR-R1-1): the round-1 version of
// this function checked stateRegister ONLY. A train whose cars all
// RETURNED (stateRegister nominal) but whose OUTCOME is hot - 'error'
// (needs-attention per board-defs.json), an unrecognised word like
// 'BLOCKED' (needs-attention, vocab.js's Law-1 fallback), even
// 'done-with-findings' (in-progress) - was wrongly treated as terminal and
// could be capped out with ZERO residual signal (the lane's own register
// stays nominal per composeRegister, and the honesty summary only ever
// says "N of M returned"). dom-writer.js's renderTrains DOES render a
// separately register-colored outcome chip per car (`car-outcome
// ${registerClass(car.outcomeRegister)}`) - so outcome severity is real,
// rendered signal this predicate must not blind itself to. Fixed: BOTH
// axes must be nominal. REJECT still ages out correctly - board-defs.json
// pins REJECT to nominal register by doctrine (a REJECT is a SUCCESS
// outcome in this shop, same posture as the gates lane) - no special case
// needed. A car with NO outcome at all (outcomeRegister null - the schema
// makes TrainCar.Outcome optional) is conservatively NOT nominal either:
// schema/starcar-artifact.schema.json requires outcome/findings/abstract
// for every kind=returned record, so a genuinely-returned car with no
// outcome would itself be a discovery, and "when in doubt, show the row"
// applies the same way it does to an unrecognised word.
//
// Anything else (rolling, stalled for adjudication, an unrecognised car
// state or outcome) is conservatively non-terminal - always visible, per
// this ticket's "when in doubt, show the row" instruction.
//
// #67 FIX CYCLE ROUND 3 (view-67-car-r3 SAME-PASS isolation sweep): the
// `c.stateRegister === 'nominal'` conjunct is DEFENCE-IN-DEPTH, not dead
// code, even though no WIRE-REALISTIC fixture can fault-inject it in
// isolation from the outcome conjunct - assemble.go sets Outcome exactly
// when a dispatch's liveness state is 'returned', and
// schema/starcar-artifact.schema.json requires outcome for every
// kind=returned record, so on the real wire outcomeRegister nominal
// already implies stateRegister nominal (a car can never carry a nominal
// outcome while its state is anything else). A future round finding this
// conjunct's own isolated fault injection green must not read that as
// "this half of the predicate does nothing" - it is protecting against a
// wire shape the schema forbids today, and removing it would be removing
// the ONLY thing stopping a future schema relaxation (or a malformed feed)
// from silently reintroducing MAJOR-R1-1's exact defect for a car whose
// state was never actually 'returned'.
function isTrainTerminal(train) {
  if (train.declaredNotObserved.length > 0) return false;
  return (
    train.cars.length > 0 &&
    train.cars.every((c) => c.stateRegister === 'nominal' && c.outcomeRegister === 'nominal')
  );
}

// #67: a train carries no top-level `at` either - its own recency signal is
// the MOST RECENT `at` among its cars (the latest thing that happened on
// this train), so capTerminalHistory's default `item.at` accessor cannot be
// reused verbatim and this custom getAt is threaded in instead.
function trainRecencyAt(train) {
  return train.cars.reduce((latest, c) => {
    if (!latest) return c.at;
    return Date.parse(c.at) > Date.parse(latest) ? c.at : latest;
  }, null);
}

// #67 (HONESTY CONSTRAINT, Law 4 + absence-blindness): hidden history is
// ASSERTED, never silent - null (never rendered) when nothing is hidden, so
// an unfiltered lane carries no noise line at all (the same honest-absence
// posture this file already uses elsewhere, e.g. lanePurpose above).
//
// #67 FIX CYCLE ROUND 2 (view-67-car-r2 NOTE-1): a DISPATCH really is
// wire-verbatim "returned" (liveness is a real state word on the wire), but
// a TRAIN never carries that word at all - "returned" here would describe
// a derived, client-side judgment as if it were the data's own vocabulary,
// which also under-describes what a hot OUTCOME (this round's own fix)
// could be hiding. `noun` is optional (dispatches keep "returned", literally
// true there); trains use the owner's exact ticket wording with no noun.
function historySummaryLine(hiddenCount, terminalTotal, noun = '') {
  if (hiddenCount <= 0) return null;
  const shown = terminalTotal - hiddenCount;
  const nounPart = noun ? ` ${noun}` : '';
  return `showing last ${shown} of ${terminalTotal}${nounPart} - full record in the store`;
}

function buildLaneBody(lane, vocab, hasRenderer) {
  if (!hasRenderer) {
    return { kind: 'no-renderer' };
  }

  switch (lane.id) {
    case 'trains': {
      const trains = lane.data.trains.map((t) => ({
        id: t.id,
        title: t.title,
        // #28: the manifest's own declared ticket refs, structured, never
        // re-parsed from title prose (assemble.Train.Tickets).
        tickets: t.tickets || [],
        declaredNotObserved: t.declaredNotObserved || [],
        cars: t.cars.map((c) => ({
          subject: c.subject,
          role: describeVocab(c.role, vocab.roles), // presentational label OK - a structural descriptor, not a data value
          gate: c.gate ?? null,
          // VERBATIM, never translated (mockup brief: "the real board
          // renders whatever state word its data source provides,
          // VERBATIM, never a translation of it") - describeVocab is
          // used ONLY for the register (color), never the displayed text.
          state: c.state,
          stateRegister: describeVocab(c.state, vocab.liveness).register,
          outcome: c.outcome ?? null,
          outcomeRegister: c.outcome ? describeVocab(c.outcome, vocab.outcomes).register : null,
          at: c.at,
          superseded: c.superseded || [],
          // #28: single-sourced from store.Record.Path server-side
          // (assemble.recordDirBySubject) - never re-derived from
          // `subject` here (Law 6).
          recordDir: c.recordDir ?? null,
          // #75: the human task-id handle, null when this car has not yet
          // returned with one - dom-writer.js falls back to `subject`
          // honestly rather than inventing a label (Law 1). `||`, not `??`
          // (fix cycle r2, R1-m1): the wire schema has no minLength, so a
          // schema-valid "" is possible even though the shipped producer
          // never stamps one (Produce-Artifact.ps1's `-and $taskId` guard) -
          // treated as absent, same as links.js:17's truthiness guard for
          // the sibling recordDir field, never a blank identity label.
          taskId: c.taskId || null
        }))
      }));
      // #67 (SCOPE EXTENSION, owner 2026-07-26 17:09): non-terminal trains
      // (rolling/queued/stalled-for-adjudication/unrecognised, per
      // isTrainTerminal above) are ALWAYS visible; fully-returned trains are
      // history, capped by recency - selection only, register computation
      // above is untouched by this call.
      const { visible, hiddenCount, terminalTotal } = capTerminalHistory(trains, {
        isTerminal: isTrainTerminal,
        getAt: trainRecencyAt
      });
      return {
        kind: 'trains',
        trains: visible,
        // #67 FIX CYCLE ROUND 2 (NOTE-1): no noun - a train is never
        // literally "returned" on the wire (only its cars carry that word),
        // so this uses the owner's exact ticket wording rather than
        // borrowing the dispatches lane's noun.
        historySummary: historySummaryLine(hiddenCount, terminalTotal)
      };
    }
    case 'gates': {
      // #12: ONE pass over this fold's gates computes every family's
      // convergence trend, keyed by array index - computeHealthTrends is
      // PURE and re-run every render (cheap: this lane's gate count, never
      // cached/persisted - Law 6, no second copy of the wire's own
      // findings text).
      const healthTrends = computeHealthTrends(lane.data.gates);
      return {
        kind: 'gates',
        gates: lane.data.gates.map((g, index) => ({
          name: g.name,
          subject: g.subject,
          outcome: g.outcome, // VERBATIM - "REJECT" stays "REJECT" (spec YB-5: rendered VERBATIM, never re-derived)
          outcomeRegister: describeVocab(g.outcome, vocab.outcomes).register,
          at: g.at,
          recordDir: g.recordDir ?? null, // #28
          healthTrend: healthTrends.get(index) ?? null // #12: present ONLY on a family's latest round
        }))
      };
    }
    case 'dispatches': {
      const dispatches = lane.data.dispatches.map((d) => ({
        subject: d.subject,
        state: d.state, // VERBATIM
        stateRegister: describeVocab(d.state, vocab.liveness).register,
        at: d.at,
        outcome: d.outcome ?? null,
        elapsedSeconds: typeof d.elapsed_seconds === 'number' ? d.elapsed_seconds : null,
        budgetSeconds: typeof d.budget_seconds === 'number' ? d.budget_seconds : null,
        budgetSource: d.budget_source ?? null,
        assigned: Boolean(d.assigned),
        recordDir: d.recordDir ?? null, // #28
        // #75: human handle, null falls back to `subject` (dom-writer.js).
        // `||`, not `??` (fix cycle r2, R1-m1): a schema-valid "" (no
        // minLength on the wire) is treated as absent, matching links.js:17's
        // truthiness guard for the sibling recordDir field - never a blank
        // identity label.
        taskId: d.taskId || null,
        superseded: d.superseded || [] // #71: same subject, same directory as recordDir above
      }));
      // #67 (owner finding after #62 live-board feedback): every non-
      // terminal / needs-attention dispatch (dispatched, overdue, presumed-
      // lost, any unrecognised state word) is ALWAYS visible; RETURNED
      // history is capped by recency. Terminality reads the row's own
      // ALREADY-COMPUTED stateRegister (nominal <=> 'returned' is the one
      // liveness state the wire's own vocab maps there) - this never
      // recomputes or hardcodes the liveness taxonomy, it only selects
      // which already-registered rows render. NOT applicable to a train's
      // hot-OUTCOME concern (#67 fix cycle round 2 MAJOR-R1-1): this
      // renderer (renderDispatches, dom-writer.js) never renders `outcome`
      // as its own register-colored element the way renderTrains does for
      // a car - the predicate here already matches everything this lane
      // actually displays as severity.
      //
      // Probed: no pre-dispatch ("queued") state exists anywhere on this
      // wire. board/fold's OWN liveness set (design S5.6) is closed to
      // exactly dispatched/overdue/returned/presumed-lost - grep of
      // board/server/*.go turned up no fifth state - so there is no
      // "queued" slot for this lane to render, none invented, per this
      // ticket's own instruction. CORRECTED (#67 fix cycle round 2
      // MINOR-R1-1): the WIRE schema itself does NOT enumerate this set -
      // schema/yard-snapshot.schema.json's $defs.dispatchesPayload declares
      // `state` as an open string (Law 7: an unrecognised value is a
      // discovery, never a validation failure), so the closed-set claim
      // belongs to board/fold alone, never to the schema.
      const { visible, hiddenCount, terminalTotal } = capTerminalHistory(dispatches, {
        isTerminal: (d) => d.stateRegister === 'nominal'
      });
      return {
        kind: 'dispatches',
        dispatches: visible,
        // Yard inventory (mockup: "visible, never hidden") - the count is
        // ALWAYS surfaced, even at zero, so its absence is never mistaken
        // for "nothing to disclose". Computed over the FULL set (never the
        // capped view) - this is a distinct honesty count from history
        // capping and must not shrink when returned history is capped.
        yardInventoryCount: dispatches.filter((d) => !d.assigned).length,
        // #67 FIX CYCLE ROUND 2 (NOTE-1): "returned" is kept here - a
        // dispatch really does carry that word verbatim on the wire, unlike
        // a train.
        historySummary: historySummaryLine(hiddenCount, terminalTotal, 'returned')
      };
    }
    case 'freight': {
      // #84: freight went live - the inbound ticket queue (GitHub Project 6
      // items in Backlog or Todo status). Empty-vs-never-run-vs-stale is NOT
      // this function's job to disambiguate: that distinction lives entirely
      // in freshness (composeLines' secondary line above - "not yet polled"
      // for never-polled, "fresh" for a genuinely-run-and-empty queue,
      // "stale, <duration>" for an aged sync) - the same Rule 2 split every
      // other live lane already follows (freshness carries the "when" story,
      // the body carries the "what"). This body only ever renders the
      // CURRENT tickets array, honestly, at whatever size it is.
      const tickets = lane.data.tickets.map((t) => ({
        number: t.number,
        title: t.title,
        status: t.status,
        url: t.url,
        recordDir: t.recordDir ?? null
      }));
      return { kind: 'freight', tickets };
    }
    case 'fuel':
      // Bagged: data exists (cost fields on some records) but is
      // deliberately not surfaced yet (#11) - the hooded-signal treatment,
      // distinct text from freight's dark absence.
      return { kind: 'bagged', text: 'data held, not surfaced' };
    default:
      // hasRendererFor already gates this branch to only the five known
      // ids when it returns true, so this default is defensive dead code
      // for a future lane id added to EXPECTED_LANE_IDS without a body
      // case here yet - never silently blank.
      return { kind: 'unknown-lane', raw: lane.data ?? null };
  }
}

