    if (i < targetIndexBefore) {
      assert.equal(
        after_.rows[i].top,
        before_.rows[i].top,
        `REGRESSION: row '${before_.rows[i].subject}' (above the expanded row) shifted position ` +
          `(${before_.rows[i].top} -> ${after_.rows[i].top})`
      );
    }
  }
});

